import { Bell } from "lucide-react";
import { useNavigate } from "react-router";
import {
  Alert,
  AlertDescription,
  AlertTitle,
} from "../ui/alert";
import {
  Dialog,
  DialogBody,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "../ui/dialog";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "../ui/tabs";
import type { TaskNotification } from "../../lib/academicSnapshotTask";

interface AcademicSnapshotNotificationsDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** The payloads generated by assignAcademicSnapshotTask (US 19988). */
  notifications: TaskNotification[];
}

// Shows the Admissions user exactly what the assigned ECR Team member was
// sent — rendered from the same payloads handed to the in-app and email
// integration points, not a separate copy of the content.
export function AcademicSnapshotNotificationsDialog({
  open,
  onOpenChange,
  notifications,
}: AcademicSnapshotNotificationsDialogProps) {
  const navigate = useNavigate();
  const inApp = notifications.find(
    (n) => n.channel === "in-app",
  );
  const email = notifications.find(
    (n) => n.channel === "email",
  );
  if (!inApp || !email) return null;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent size="lg">
        <DialogHeader>
          <DialogTitle>Notifications Sent</DialogTitle>
          <DialogDescription>
            To: {inApp.recipient.name} ({inApp.recipient.email})
          </DialogDescription>
        </DialogHeader>
        <DialogBody>
          <Tabs defaultValue="in-app">
            <TabsList>
              <TabsTrigger value="in-app">In-app</TabsTrigger>
              <TabsTrigger value="email">Email</TabsTrigger>
            </TabsList>

            <TabsContent value="in-app">
              <Alert
                variant="info"
                action={{
                  label: inApp.content.ctaLabel,
                  onClick: () => {
                    onOpenChange(false);
                    navigate(inApp.link);
                  },
                }}
              >
                <Bell />
                <AlertTitle>{inApp.content.title}</AlertTitle>
                <AlertDescription>
                  <p>
                    You have been assigned an Academic Snapshot
                    task for{" "}
                    <strong>{inApp.content.youthName}</strong>.
                  </p>
                  {inApp.content.details.map((d) => (
                    <p key={d.label}>
                      {d.label}: {d.value}
                    </p>
                  ))}
                </AlertDescription>
              </Alert>
            </TabsContent>

            <TabsContent value="email">
              <DialogDescription>
                Subject: {email.content.subject}
              </DialogDescription>
              <iframe
                title="Email notification body"
                srcDoc={email.html}
                sandbox="allow-popups allow-popups-to-escape-sandbox"
                className="mt-2 h-[420px] w-full rounded-lg border"
              />
            </TabsContent>
          </Tabs>
        </DialogBody>
      </DialogContent>
    </Dialog>
  );
}